seen=$(forge pr list --head "$BRANCH" --state merged --json number,headRefOid,mergeCommit --jq '.[0] | select(. != null) | [.number, .headRefOid, .mergeCommit.oid] | @tsv')
[ -n "$seen" ] || { echo "no merged pull request carries $BRANCH: there is no proof to close with" >&2; exit 1; }
number=$(printf '%s' "$seen" | cut -f1); head=$(printf '%s' "$seen" | cut -f2); commit=$(printf '%s' "$seen" | cut -f3)
[ -n "$commit" ] && [ "$commit" != null ] || commit=$head
git fetch --quiet origin
trunk=$(git rev-parse "refs/remotes/origin/$BASE")
git merge-base --is-ancestor "$head" "$trunk" || { echo "the remote $BASE does not carry $head" >&2; exit 1; }
