printf '{"issue":"%s","state":"%s"}' "$ISSUE" "$state"

set -eu
found=$(git -C "$REPO" worktree list --porcelain | awk -v want="branch refs/heads/$BRANCH" '
    /^worktree / { path = substr($0, 10); locked = 0 }
    /^locked/ { locked = 1 }
    $0 == want { hit = path }
    /^$/ { if (hit != "" && out == "") { out = hit; lock = locked } hit = "" }
    END { if (hit != "" && out == "") { out = hit; lock = locked } if (out != "") print lock "\t" out }')
if [ -z "$found" ]; then
    printf '{"removed":""}'
    exit 0
fi
locked=$(printf '%s' "$found" | cut -f1); path=$(printf '%s' "$found" | cut -f2)
here=$(cd "$(git -C "$REPO" rev-parse --show-toplevel)" && pwd -P)
there=$(cd "$path" 2>/dev/null && pwd -P || printf '%s' "$path")
[ "$here" != "$there" ] || { echo "the worktree holding $BRANCH is the repo this flow runs from: name the main checkout as repo instead" >&2; exit 1; }
[ "$locked" = 0 ] || { echo "the worktree $path is locked: whoever holds it unlocks it when they have finished reading" >&2; exit 1; }
git -C "$REPO" worktree remove "$path" >&2
printf '{"removed":"%s"}' "$path"

set -eu
policy_now=$(cd "$REPO" && sailor policy) || { echo "the delivery policy could not be re-read from the trusted trunk" >&2; exit 1; }
policy_was=$(printf '%s' "$POLICY_READ" | python3 -c 'import json,sys; p=json.load(sys.stdin); print("merge: %s\npush: %s\nrelease: %s\n%s" % (p["merge"], p["push"], p["release"], p["read_from"]))')
[ "$policy_now" = "$policy_was" ] || { echo "the delivery policy changed since it was read: the authorization in flight no longer holds; run the flow again" >&2; exit 1; }
url=$(git -C "$REPO" remote get-url origin) || { echo "the tree has no origin remote" >&2; exit 1; }
set -- -C "$REPO"
case "$url" in
    /*|file://*) ;;
    http://*|https://*)
        push_as=$(git -C "$REPO" config --get sailor.pushAs) || { echo "sailor.pushAs is not declared on this tree: refusing to push with the machine's own credentials" >&2; exit 1; }
        helper='!f() { printf "%s\\n" username=x-access-token; printf "password=%s\\n" "$(gh auth token --user "'"$push_as"'")"; }; f'
        set -- -C "$REPO" -c credential.helper= -c "credential.helper=$helper" ;;
    *) echo "origin is $url: a push over it cannot be bound to sailor.pushAs, so this flow refuses it" >&2; exit 1 ;;
esac
git -C "$REPO" fetch --quiet origin
trunk=$(git -C "$REPO" rev-parse "refs/remotes/origin/$BASE")
tip=$(git -C "$REPO" ls-remote origin "refs/heads/$BRANCH" | awk '{ print $1 }')
if [ -n "$tip" ]; then
    git -C "$REPO" merge-base --is-ancestor "$tip" "$trunk" || { echo "the remote $BRANCH at $tip carries commits the remote $BASE does not" >&2; exit 1; }
    git "$@" push --force-with-lease="refs/heads/$BRANCH:$tip" origin ":refs/heads/$BRANCH" >&2
fi
printf '{"deleted":"%s"}' "$tip"

